#!/usr/bin/env python3
from pathlib import Path
import shutil, zlib, base64

ROOT = Path(__file__).resolve().parent
DATA = """"""
raw = zlib.decompress(base64.b64decode(DATA)).decode("utf-8")
parts = raw.split("@@FILE@@")[1:]

files = {}
for part in parts:
    name, content = part.split("\n", 1)
    files[name] = content

print("=== PORTAIL DES CANARDS — MISE À JOUR ===")
for name, content in files.items():
    target = ROOT / name
    if target.exists():
        backup = target.with_name(target.name + ".bak")
        shutil.copy2(target, backup)
        print(f"backup : {backup.name}")
    target.write_text(content, encoding="utf-8")
    print(f"updated: {name}")

print("\nMise à jour terminée.")
print("Les anciens fichiers sont conservés en .bak")
print("Teste maintenant avec :")
print("  node --check game.js")
print("  node --check map.js")
print("  node --check player.js")
print("  node --check npc.js")
print("  node --check quest.js")
print("  node --check prologue.js")
